// For each due post, dispatch to the per-channel outgoing webhook URL
// configured via PINTEREST_WEBHOOK_URL / X_WEBHOOK_URL / INSTAGRAM_WEBHOOK_URL.
// If a channel has no URL configured, mark the post 'ready_for_export' so the
// dashboard can surface it for manual handling. This avoids implementing the
// full Pinterest/X/Instagram OAuth+API flows here while still providing a real
// integration path (Buffer, Make.com, n8n's own social nodes, etc.).

const envByChannel = {
  pinterest: process.env.PINTEREST_WEBHOOK_URL,
  x:         process.env.X_WEBHOOK_URL,
  instagram: process.env.INSTAGRAM_WEBHOOK_URL
};

const out = [];
for (const item of $input.all()) {
  const post = item.json;
  const url  = envByChannel[post.channel];

  if (!url) {
    out.push({ json: { _kind: 'mark', id: post.id, status: 'ready_for_export', error: null } });
    continue;
  }

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers: { 'Content-Type': 'application/json' },
      body: {
        post_id:       post.id,
        listing_id:    post.listing_id,
        channel:       post.channel,
        copy:          post.copy,
        image_path:    post.image_path,
        scheduled_for: post.scheduled_for
      },
      json: true,
      timeout: 30000,
      // Treat any 2xx as success. Non-2xx throws and lands in catch.
      ignoreHttpStatusErrors: false
    });
    out.push({ json: { _kind: 'mark', id: post.id, status: 'posted', error: null, response: res } });
  } catch (e) {
    out.push({ json: { _kind: 'mark', id: post.id, status: 'failed', error: String(e?.message || e).slice(0, 500) } });
  }
}

// Always emit a tail summary item (won't be marked, just used for logs).
out.push({ json: { _kind: 'summary', dispatched: $input.all().length } });
return out;
